const fullName = $input.first().json.fullName;
const projectTopic = $input.first().json.projectTopic;
const department = $input.first().json.department;
const matricNumber = $input.first().json.matricNumber;
const schoolName = $input.first().json.schoolName;
const additionalInstructions = $input.first().json.additionalInstructions;

// Create comprehensive context for all sections
const projectContext = {
  studentName: fullName,
  topic: projectTopic,
  department: department,
  matricNumber: matricNumber,
  school: schoolName,
  instructions: additionalInstructions,

  // This will be populated by each section
  section1_content: "",
  section2_content: "",
  section3_content: "",
  section4_content: "",
  section5_content: ""
};

return [{
  json: {
    ...projectContext,
    email: $input.first().json.email
  }
}];

const data = $('Parse Section 1 Content').item.json;

const content = data.section1Content;
const abstract = data.abstractText || '';

const studentName = $('Extract Student Info').item.json.fullName;
const projectTopic = $('Extract Student Info').item.json.projectTopic;
const projectId = $('Extract Student Info').item.json.projectId;
const department = $('Extract Student Info').item.json.department;

// Header
const documentHeader = `
═══════════════════════════════════════════════════════════════
${projectTopic.toUpperCase()}
═══════════════════════════════════════════════════════════════

By: ${studentName}
Department: ${department}
Project ID: ${projectId}

SECTION 1: FRONT MATTER
(Declaration - Certification - Approval - Dedication - Acknowledgement - Abstract)

═══════════════════════════════════════════════════════════════
`;

// Combine content + abstract
const fullDocument =
  documentHeader +
  "\n\n" +
  content +
  "\n\n" +
  "ABSTRACT\n" +
  abstract;

// Base64
const base64Content = Buffer.from(fullDocument).toString('base64');

return {
  json: {
    fileName: `Section_1_Front_Matter_${projectId}.txt`,
    fileContent: fullDocument,
    base64Content,
    mimeType: 'text/plain',
    sectionNumber: 1
  }
};

const content = $('Parse Section 2 Content').item.json.section2Content;
const studentName = $('Extract Student Info').item.json.fullName;
const projectTopic = $('Extract Student Info').item.json.projectTopic;
const projectId = $('Extract Student Info').item.json.projectId;
const department = $('Extract Student Info').item.json.department;

// Create document header
const documentHeader = `
═══════════════════════════════════════════════════════════════
${projectTopic.toUpperCase()}
═══════════════════════════════════════════════════════════════

By: ${studentName}
Department: ${department}
Project ID: ${projectId}

SECTION 2: CHAPTER ONE - INTRODUCTION

═══════════════════════════════════════════════════════════════

`;

const fullDocument = documentHeader + "\n\n" + content;

// Convert to base64
const base64Content = Buffer.from(fullDocument).toString('base64');

return {
  json: {
    fileName: `Section_2_Chapter_1_Introduction_${projectId}.txt`,
    fileContent: fullDocument,
    base64Content: base64Content,
    mimeType: 'text/plain',
    sectionNumber: 2
  }
};

const data = $('Parse Section 3 Content').item.json;

const theoreticalFramework = data.theoreticalFramework || '';
const summaryOfReviewedWorks = data.section3Content || '';
const researchGap = data.researchGap || '';

const studentName = $('Extract Student Info').item.json.fullName;
const projectTopic = $('Extract Student Info').item.json.projectTopic;
const projectId = $('Extract Student Info').item.json.projectId;
const department = $('Extract Student Info').item.json.department;

const documentHeader = `
═══════════════════════════════════════════════════════════════
${projectTopic.toUpperCase()}
═══════════════════════════════════════════════════════════════

By: ${studentName}
Department: ${department}
Project ID: ${projectId}

SECTION 3: CHAPTER TWO - LITERATURE REVIEW

═══════════════════════════════════════════════════════════════
`;

// Academic structure — ORDER MATTERS
const fullDocument =
  documentHeader +
  "\n\n" +
  "2.1 THEORETICAL FRAMEWORK\n" +
  theoreticalFramework +
  "\n\n" +
  "2.3 SUMMARY OF REVIEWED WORKS\n" +
  summaryOfReviewedWorks +
  "\n\n" +
  "2.4 RESEARCH GAP\n" +
  researchGap;

// Encode
const base64Content = Buffer.from(fullDocument).toString('base64');

return {
  json: {
    fileName: `Section_3_Chapter_2_Literature_Review_${projectId}.txt`,
    fileContent: fullDocument,
    base64Content,
    mimeType: 'text/plain',
    sectionNumber: 3
  }
};

const content = $('Parse Section 4 Content').item.json.section4Content;
const studentName = $('Extract Student Info').item.json.fullName;
const projectTopic = $('Extract Student Info').item.json.projectTopic;
const projectId = $('Extract Student Info').item.json.projectId;
const department = $('Extract Student Info').item.json.department;

const documentHeader = `
═══════════════════════════════════════════════════════════════
${projectTopic.toUpperCase()}
═══════════════════════════════════════════════════════════════

By: ${studentName}
Department: ${department}
Project ID: ${projectId}

SECTION 4: CHAPTER THREE - RESEARCH METHODOLOGY

═══════════════════════════════════════════════════════════════

`;

const fullDocument = documentHeader + "\n\n" + content;

const base64Content = Buffer.from(fullDocument).toString('base64');

return {
  json: {
    fileName: `Section_4_Chapter_3_Methodology_${projectId}.txt`,
    fileContent: fullDocument,
    base64Content: base64Content,
    mimeType: 'text/plain',
    sectionNumber: 4
  }
};

const aiResponse = $input.item.json.output || $input.item.json.text || $input.item.json;

let fullContent = '';
if (typeof aiResponse === 'string') {
  fullContent = aiResponse;
} else if (aiResponse.content) {
  fullContent = aiResponse.content;
} else if (aiResponse.output) {
  fullContent = aiResponse.output;
}

// Extract implementation section
const implMatch = fullContent.match(/4\.1\s*SYSTEM IMPLEMENTATION[\s\S]*?(?=4\.2|$)/i);
const implementation = implMatch ? implMatch[0] : '';

// Extract challenges section
const challengesMatch = fullContent.match(/4\.2\s*CHALLENGES[\s\S]*?(?=4\.3|$)/i);
const challenges = challengesMatch ? challengesMatch[0] : '';

// Extract individual challenges
const challengesList = [];
const challengePattern = /\*\*Challenge\s+\d+:.*?\*\*([\s\S]*?)(?=\*\*Challenge\s+\d+:|\*\*|4\.3|$)/gi;
let match;
while ((match = challengePattern.exec(challenges)) !== null) {
  challengesList.push(match[0].trim());
}

// Extract testing and results section
const resultsMatch = fullContent.match(/4\.3\s*TESTING AND RESULTS[\s\S]*?(?=4\.4|$)/i);
const results = resultsMatch ? resultsMatch[0] : '';

// Extract discussion section
const discussionMatch = fullContent.match(/4\.4\s*DISCUSSION OF RESULTS[\s\S]*?(?=CHAPTER 5|$)/i);
const discussion = discussionMatch ? discussionMatch[0] : '';

// Extract technologies/tools mentioned
const technologies = [];
const techPattern = /(?:using|with|implemented in|built with|developed using)\s+([A-Z][a-zA-Z0-9+#\s.]+?)(?:\s+(?:and|,|to|for|was|were)|\.|$)/gi;
while ((match = techPattern.exec(implementation)) !== null) {
  const tech = match[1].trim();
  if (tech.length < 30 && !technologies.includes(tech)) {
    technologies.push(tech);
  }
}

// Count test results mentioned
const testCount = (fullContent.match(/test\s+case|unit\s+test|integration\s+test/gi) || []).length;

return {
  json: {
    chapter4Content: fullContent,
    implementation: implementation,
    challenges: challenges,
    challengesList: challengesList,
    challengeCount: challengesList.length,
    results: results,
    discussion: discussion,
    technologies: technologies,
    testCount: testCount,
    pageCount: 14, // Estimated 12-15 pages
    chapterNumber: 4
  }
};

// Safely get parsed Chapter 4 data with fallbacks
let implementation = $input.first().json.implementation;
let challenges = $input.first().json.challenges;
let results = $input.first().json.results;
let discussion = $input.first().json.discussion;
let chapter4Content = $input.first().json.chapter4Content;

try {
  const data = $('Parse Chapter 4 Content').item.json;
  implementation = data.implementation || '';
  challenges = data.challenges || '';
  results = data.results || '';
  discussion = data.discussion || '';
  chapter4Content = data.chapter4Content || '';
} catch (error) {
  // If node doesn't exist, try alternate node name or use empty strings
  console.log('Parse Chapter 4 Content node not found, using fallbacks');
}

// Safely get student info with fallbacks
let studentName = 'Student Name';
let projectTopic = 'Project Topic';
let projectId = 'PROJECT_ID';
let department = 'Department';

try {
  const studentInfo = $('Extract Student Info').item.json;
  studentName = studentInfo.fullName || 'Student Name';
  projectTopic = studentInfo.projectTopic || 'Project Topic';
  projectId = studentInfo.projectId || 'PROJECT_ID';
  department = studentInfo.department || 'Department';
} catch (error) {
  console.log('Extract Student Info node not found, using defaults');
}

// Create document header
const documentHeader = `
═══════════════════════════════════════════════════════════════
${projectTopic.toUpperCase()}
═══════════════════════════════════════════════════════════════

By: ${studentName}
Department: ${department}
Project ID: ${projectId}

SECTION 4A: CHAPTER FOUR - IMPLEMENTATION AND RESULTS

═══════════════════════════════════════════════════════════════
`;

// Academic structure — ORDER MATTERS
const fullDocument =
  documentHeader +
  "\n\n" +
  "CHAPTER 4: IMPLEMENTATION AND RESULTS\n\n" +
  "4.1 SYSTEM IMPLEMENTATION\n" +
  implementation +
  "\n\n" +
  "4.2 CHALLENGES ENCOUNTERED AND SOLUTIONS\n" +
  challenges +
  "\n\n" +
  "4.3 TESTING AND RESULTS\n" +
  results +
  "\n\n" +
  "4.4 DISCUSSION OF RESULTS\n" +
  discussion;

// Encode
const base64Content = Buffer.from(fullDocument).toString('base64');

return {
  json: {
    fileName: `Section_4A_Chapter_4_Implementation_Results_${projectId}.txt`,
    fileContent: fullDocument,
    base64Content,
    mimeType: 'text/plain',
    sectionNumber: 4,
    chapterNumber: 4
  }
};

const aiResponse = $input.item.json.output || $input.item.json.text || $input.item.json;

let fullContent = '';
if (typeof aiResponse === 'string') {
  fullContent = aiResponse;
} else if (aiResponse.content) {
  fullContent = aiResponse.content;
} else if (aiResponse.output) {
  fullContent = aiResponse.output;
}

// Extract summary section
const summaryMatch = fullContent.match(/5\.1\s*SUMMARY AND CONCLUSION[\s\S]*?(?=5\.2|$)/i);
const summary = summaryMatch ? summaryMatch[0] : '';

// Extract contributions section
const contribMatch = fullContent.match(/5\.2\s*CONTRIBUTIONS[\s\S]*?(?=5\.3|$)/i);
const contributions = contribMatch ? contribMatch[0] : '';

// Extract limitations section
const limMatch = fullContent.match(/5\.3\s*LIMITATIONS[\s\S]*?(?=5\.4|$)/i);
const limitations = limMatch ? limMatch[0] : '';

// Extract recommendations section
const recsMatch = fullContent.match(/5\.4\s*RECOMMENDATIONS[\s\S]*?(?=5\.5|$)/i);
const recommendations = recsMatch ? recsMatch[0] : '';

// Extract future work section
const futureMatch = fullContent.match(/5\.5\s*FUTURE WORK[\s\S]*?(?=5\.6|$)/i);
const futureWork = futureMatch ? futureMatch[0] : '';

// Extract final conclusion
const finalMatch = fullContent.match(/5\.6\s*FINAL CONCLUSION[\s\S]*$/i);
const finalConclusion = finalMatch ? finalMatch[0] : '';

// Extract all recommendations into a list
const recsList = [];
const recsPattern = /\*Recommendation\s+\d+:([^\*]+?)(?=\*Recommendation|\*\*|5\.|$)/gis;
let match;
while ((match = recsPattern.exec(recommendations)) !== null) {
  const recText = match[1].trim();
  if (recText.length > 50) {
    recsList.push(recText);
  }
}

// Categorize recommendations
const systemImprovements = [];
const futureResearch = [];
const practitionerRecs = [];

recommendations.split(/\*\*[A-Z]\./).forEach(section => {
  if (section.includes('System Improvement')) {
    systemImprovements.push(section.trim());
  } else if (section.includes('Future Research')) {
    futureResearch.push(section.trim());
  } else if (section.includes('Practitioners')) {
    practitionerRecs.push(section.trim());
  }
});

return {
  json: {
    chapter5Content: fullContent,
    summary: summary,
    contributions: contributions,
    limitations: limitations,
    recommendations: recommendations,
    futureWork: futureWork,
    finalConclusion: finalConclusion,
    recommendationsList: recsList,
    recommendationCount: recsList.length,
    systemImprovements: systemImprovements,
    futureResearchAreas: futureResearch,
    practitionerRecommendations: practitionerRecs,
    chapterNumber: 5
  }
};

// Get parsed Chapter 5 data
const data = $('Parse Chapter 5 Content').item.json;
const summary = data.summary || '';
const contributions = data.contributions || '';
const limitations = data.limitations || '';
const recommendations = data.recommendations || '';
const futureWork = data.futureWork || '';

// Get student info
const studentName = $('Extract Student Info').item.json.fullName;
const projectTopic = $('Extract Student Info').item.json.projectTopic;
const projectId = $('Extract Student Info').item.json.projectId;
const department = $('Extract Student Info').item.json.department;

// Create document header
const documentHeader = `
═══════════════════════════════════════════════════════════════
${projectTopic.toUpperCase()}
═══════════════════════════════════════════════════════════════

By: ${studentName}
Department: ${department}
Project ID: ${projectId}

SECTION 4B: CHAPTER FIVE - CONCLUSION AND RECOMMENDATIONS

═══════════════════════════════════════════════════════════════
`;

// Academic structure — ORDER MATTERS
const fullDocument =
  documentHeader +
  "\n\n" +
  "CHAPTER 5: CONCLUSION AND RECOMMENDATIONS\n\n" +
  "5.1 SUMMARY AND CONCLUSION\n" +
  summary +
  "\n\n" +
  "5.2 CONTRIBUTIONS TO KNOWLEDGE AND INDUSTRY\n" +
  contributions +
  "\n\n" +
  "5.3 LIMITATIONS AND CONSTRAINTS\n" +
  limitations +
  "\n\n" +
  "5.4 RECOMMENDATIONS\n" +
  recommendations +
  "\n\n" +
  "5.5 FUTURE WORK\n" +
  futureWork;

// Encode
const base64Content = Buffer.from(fullDocument).toString('base64');

return {
  json: {
    fileName: `Section_4B_Chapter_5_Conclusion_${projectId}.txt`,
    fileContent: fullDocument,
    base64Content,
    mimeType: 'text/plain',
    sectionNumber: 5,
    chapterNumber: 5
  }
};
